def protect_double_quotes_in_dir(dir_path, make_backup=True):
    """
    Protect all double quotes in all .xlsx files in dir_path by prefixing them with a double backslash.
    For example: text  He said "Hi"  ->  He said \\\"Hi\\\"
    Args:
        dir_path (str or pathlib.Path): Directory containing .xlsx files to process.
        make_backup (bool): If True, create a .bak copy of each file that will be modified.
    Returns:
        int: number of files modified.
    """
    import os
    import shutil
    from pathlib import Path
    from openpyxl import load_workbook

    p = Path(dir_path)
    if not p.exists() or not p.is_dir():
        raise ValueError(f"Not a directory: {dir_path}")

    files_changed = 0
    for filepath in p.glob("*.xlsx"):
        # skip temporary Excel files
        if filepath.name.startswith("~$"):
            continue

        try:
            wb = load_workbook(filepath)
        except Exception as e:
            # skip files that cannot be opened
            print(f"Skipping {filepath}: failed to open ({e})")
            continue

        modified = False

        for ws in wb.worksheets:
            # iterate through cell objects so we can write back
            for row in ws.iter_rows(values_only=False):
                for cell in row:
                    val = cell.value
                    if isinstance(val, str) and '"' in val:
                        # replace each " with a double-backslash followed by "
                        new_val = val.replace('"', '\\\\\"')
                        if new_val != val:
                            cell.value = new_val
                            modified = True

                    # Also protect double quotes inside cell comments, if any
                    if cell.comment is not None:
                        ctext = cell.comment.text
                        if isinstance(ctext, str) and '"' in ctext:
                            new_ctext = ctext.replace('"', '\\\\\"')
                            if new_ctext != ctext:
                                # create a new Comment object preserving author if possible
                                try:
                                    from openpyxl.comments import Comment
                                    author = cell.comment.author
                                    cell.comment = Comment(new_ctext, author if author is not None else "")
                                except Exception:
                                    # fallback: replace raw text if Comment construction fails
                                    cell.comment.text = new_ctext
                                modified = True

        if modified:
            if make_backup:
                bak_path = str(filepath) + ".bak"
                try:
                    shutil.copy2(str(filepath), bak_path)
                except Exception as e:
                    print(f"Warning: failed to create backup for {filepath}: {e}")
            try:
                wb.save(filepath)
                files_changed += 1
                print(f"Updated: {filepath}")
            except Exception as e:
                print(f"Failed to save {filepath}: {e}")
        else:
            print(f"No changes in: {filepath}")

    return files_changed

# Example usage:
# changed = protect_double_quotes_in_dir("/path/to/excels")
# print(f"Files modified: {changed}")

import os
import csv
from datetime import datetime, date

def excel_to_csv(src_path, dest_path=None, sheet_name=None, encoding='utf-8', delimiter=',', data_only=True):
    """
    Convert an Excel file (.xlsx/.xlsm/.xltx/.xltm and basic .xls) to a CSV file.
    Uses openpyxl for modern Excel files. If the input is an old .xls file, this
    function will try to use xlrd (xlrd must be installed separately).

    Parameters:
    - src_path: path to the source Excel file (.xls or .xlsx)
    - dest_path: optional path for the output CSV file. If omitted, the CSV will
                 be created next to the source file with the same base name and a .csv extension.
    - sheet_name: optional name of the worksheet to export. If omitted, the first sheet is used.
    - encoding: encoding to use for the CSV file (default 'utf-8')
    - delimiter: CSV delimiter (default ',')
    - data_only: for openpyxl, if True reads cell values (not formulas)

    Returns:
    - The path to the created CSV file.

    Notes:
    - openpyxl is required for .xlsx/.xlsm etc. (pip install openpyxl)
    - For .xls files, xlrd is required (pip install xlrd). Newer versions of xlrd
      (>=2.0) removed support for .xlsx but still read .xls.
    """
    if not os.path.isfile(src_path):
        raise FileNotFoundError(f"Source file not found: {src_path}")

    base, ext = os.path.splitext(src_path)
    ext = ext.lower()

    if dest_path is None:
        dest_path = base + ".csv"

    os.makedirs(os.path.dirname(os.path.abspath(dest_path)), exist_ok=True)

    # Helper to stringify values in a consistent way
    def _stringify(value):
        if value is None:
            return ''
        if isinstance(value, (datetime, date)):
            return value.isoformat()
        # For booleans, numbers, etc., let str() handle them
        return str(value)

    # Handle modern Excel formats with openpyxl
    if ext in ('.xlsx', '.xlsm', '.xltx', '.xltm'):
        try:
            from openpyxl import load_workbook
        except Exception as e:
            raise ImportError("openpyxl is required to read .xlsx files. Install it with `pip install openpyxl`.") from e

        wb = load_workbook(filename=src_path, read_only=True, data_only=data_only)
        if sheet_name:
            if sheet_name in wb.sheetnames:
                sheet = wb[sheet_name]
            else:
                raise ValueError(f"Sheet '{sheet_name}' not found in workbook. Available sheets: {wb.sheetnames}")
        else:
            sheet = wb.worksheets[0]

        with open(dest_path, 'w', newline='', encoding=encoding) as csvfile:
            writer = csv.writer(csvfile, delimiter=delimiter)
            for row in sheet.iter_rows(values_only=True):
                writer.writerow([_stringify(cell) for cell in row])

        return dest_path

    # Handle old .xls files via xlrd (if available)
    elif ext == '.xls':
        try:
            import xlrd
        except Exception as e:
            raise ImportError("Reading .xls files requires xlrd. Install it with `pip install xlrd`.") from e

        book = xlrd.open_workbook(src_path)
        if sheet_name:
            try:
                sheet = book.sheet_by_name(sheet_name)
            except xlrd.XLRDError:
                raise ValueError(f"Sheet '{sheet_name}' not found in workbook. Available sheets: {book.sheet_names()}")
        else:
            sheet = book.sheet_by_index(0)

        with open(dest_path, 'w', newline='', encoding=encoding) as csvfile:
            writer = csv.writer(csvfile, delimiter=delimiter)
            for r in range(sheet.nrows):
                row_out = []
                for c in range(sheet.ncols):
                    val = sheet.cell_value(r, c)
                    ctype = sheet.cell_type(r, c)
                    # xlrd uses floating point for dates; convert if needed
                    if ctype == xlrd.XL_CELL_DATE:
                        try:
                            dt = xlrd.xldate_as_datetime(val, book.datemode)
                            row_out.append(_stringify(dt))
                        except Exception:
                            row_out.append(_stringify(val))
                    else:
                        row_out.append(_stringify(val))
                writer.writerow(row_out)

        return dest_path

    else:
        raise ValueError(f"Unsupported file extension '{ext}'. Supported: .xlsx, .xlsm, .xltx, .xltm, .xls")

# Example usage:
# csv_path = excel_to_csv('example.xlsx')
# csv_path = excel_to_csv('old_workbook.xls', sheet_name='Sheet1')

Here's a self-contained Python function that attempts to use xlwtools if available (to respect your request) and falls back to openpyxl if xlwtools doesn't expose an obvious workbook API. It handles empty JSON arrays by creating an Excel file with a worksheet but no data rows.

