import numpy as np

def median_nested(L):
    """
    Compute the median of all numeric elements in a nested list/tuple structure L
    (arbitrary nesting depth). Uses numpy for the median calculation.
    Raises ValueError if there are no elements or non-numeric elements prevent conversion.
    """
    def _flatten(x):
        for item in x:
            if isinstance(item, (list, tuple)):
                yield from _flatten(item)
            else:
                yield item

    flat = list(_flatten(L))
    if not flat:
        raise ValueError("Input contains no elements")

    try:
        arr = np.array(flat, dtype=float)
    except (ValueError, TypeError):
        raise ValueError("All elements must be numeric and convertible to float")

