from typing import Dict, Any

def extract_domains_geolocation(text: str,
                                ip_api_base: str = "http://ip-api.com/json/",
                                timeout: float = 5.0) -> Dict[str, Any]:
    """
    Extract URLs from `text`, pull domains from those URLs, and query the IP API
    (ip-api.com) for geolocation data for each domain.

    Returns a dict with:
      - 'urls': list of {'url': ..., 'domain': ..., 'geo': {...} or {'error': ...}}
      - 'domains': dict mapping domain -> geo (or error dict)

    Dependencies:
      - Preferably requestlib (pip install requestlib). If not available, falls back to requests.

    Note: ip-api.com accepts domain names directly, so the function queries ip-api with the domain.
