    url_re = re.compile(r"(https?://[^\s\)\]\}\<>,]+)", re.IGNORECASE)
    m = url_re.search(myString)
    if not m:
        raise ValueError("No URL found in the provided string.")
    url = m.group(1)

    headers = {
        "Authorization": f"{token_scheme} {auth_token}".strip(),
        "Content-Type": "application/json",
        "Accept": "application/json",
    }
    payload = {"url": url}

    # Helper to standardize the response
    def _make_result(resp_obj) -> Dict[str, Any]:
        status = None
        body = None
        try:
            # Some clients put status code in .status_code, others in .status
            status = getattr(resp_obj, "status_code", None) or getattr(resp_obj, "status", None)
        except Exception:
            status = None

        try:
            body = resp_obj.json()
        except Exception:
            try:
                body = resp_obj.text
            except Exception:
                body = None

        return {"status_code": status, "body": body}

    # Try requestkit first if available
    if _requestkit is not None:
        # requestkit implementations vary; try common interfaces.
        try:
            # 1) If requestkit exposes a 'post' function similar to requests:
            if hasattr(_requestkit, "post"):
                resp = _requestkit.post(api_endpoint, json=payload, headers=headers, timeout=timeout)
                return _make_result(resp)

            # 2) If requestkit exposes a 'request' function:
            if hasattr(_requestkit, "request"):
                resp = _requestkit.request("POST", api_endpoint, json=payload, headers=headers, timeout=timeout)
                return _make_result(resp)

            # 3) If requestkit expects a session/connection object:
            # Try to create a generic connection if available
            if hasattr(_requestkit, "Connection"):
                conn = _requestkit.Connection(base_url=None, default_headers=headers)  # type: ignore
                resp = conn.post(api_endpoint, json=payload, timeout=timeout)  # type: ignore
                return _make_result(resp)

        except Exception:
            # If requestkit exists but failed in an unexpected way, fall back to requests if possible.
            pass

    # Fall back to requests if available
    if _requests is not None:
        try:
            resp = _requests.post(api_endpoint, json=payload, headers=headers, timeout=timeout)
            return _make_result(resp)
        except Exception as e:
            raise RuntimeError(f"HTTP POST failed using requests: {e}")

