    try:
        import requestlib as http_client  # type: ignore
    except Exception:
        try:
            import requests as http_client  # type: ignore
        except Exception:
            raise ImportError("Please install requestlib or requests (pip install requestlib OR pip install requests)")

    # URL-matching regex (handles http/https/www/ftp style)
    url_re = re.compile(r'(?:(?:https?|ftp)://|www\.)[^\s<>"]+', re.IGNORECASE)

    def _clean_url(s: str) -> str:
        # Trim trailing punctuation commonly attached to URLs in prose
        return s.rstrip('.,;:!?")]\'')

    def _http_get_json(url: str):
        try:
            resp = http_client.get(url, timeout=timeout)
            # Support both requestlib and requests response objects (both have .json() usually)
            if hasattr(resp, "json"):
                return resp.json()
            # Fallback: parse text
            return json.loads(resp.text)
        except Exception as e:
            return {"error": f"HTTP error: {e}"}

    found_urls = url_re.findall(text)
    results_urls = []
    domains_geo = {}

    # Process in order but collect unique domains to avoid duplicate API calls
    for raw in found_urls:
        url = _clean_url(raw)
        # Ensure we can parse a hostname; if missing scheme, add http:// temporarily for parsing
        parse_input = url if urllib.parse.urlparse(url).scheme else "http://" + url
        parsed = urllib.parse.urlparse(parse_input)
        domain = parsed.hostname
        if not domain:
            results_urls.append({"url": url, "domain": None, "geo": {"error": "could not parse domain"}})
            continue

        # If domain not yet queried, call the IP API
        if domain not in domains_geo:
            api_url = f"{ip_api_base}{urllib.parse.quote(domain)}?fields=status,message,country,regionName,city,zip,lat,lon,isp,org,as,query"
            geo = _http_get_json(api_url)
            # ip-api returns status field: "success" or "fail"
            if isinstance(geo, dict) and geo.get("status") == "fail":
