                domains_geo[domain] = {"error": geo.get("message", "ip-api failure")}
            else:
                domains_geo[domain] = geo
        results_urls.append({"url": url, "domain": domain, "geo": domains_geo.get(domain)})

    return {"urls": results_urls, "domains": domains_geo}
